import json
b = json.load(open('baseline-packages.json'))
a = json.load(open('after-cpm-packages.json'))
def extract(d):
    r = {}
    for p in d.get('projects',[]):
        name = p['path'].split('/')[-1]
        for fw in p.get('frameworks',[]):
            for pkg in fw.get('topLevelPackages',[]):
                r[(name, pkg['id'])] = pkg['resolvedVersion']
    return r
bp, ap = extract(b), extract(a)
if bp == ap:
    print('ALL IDENTICAL - no version changes')
else:
    for k in sorted(set(list(bp.keys()) + list(ap.keys()))):
        if bp.get(k) != ap.get(k):
            print(f'DIFF: {k}: {bp.get(k)} -> {ap.get(k)}')
"

